StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			UPS Data - Coromatic
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
// REQ: 			CS141 module - MTCP                                                                                                                                                                                                                                                                                                                             
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2026-03-27		William Veim			Initial release
//	2.0.0				2025-04-17		William Veim			Rework - Moved modbus configuration to FB 
//
//===============================================================================================================================
 
  (*************************************************************************
 *	CONGIURING MODBUS REQUEST
 *************************************************************************)
 
Inp_Request[0].Enable :=TRUE;
Inp_Request[0].NodeAdr := 1;
Inp_Request[0].FunctionCode := eFun#Fn03_ReadHoldingRegisters;
Inp_Request[0].Read.StartAddressLocal :=0;
Inp_Request[0].Read.StartAddressRemote := 0;
Inp_Request[0].Read.Count := 85; 
 
 (*************************************************************************
 *	UPDATING VARIABELS
 *************************************************************************)

Ext_UPS_Data.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA

//Communication state
IF Inp_Request[0].Status.Success AND NOT Inp_Request[0].Status.Error THEN
	Wrk_CommState:=TRUE;
ELSE
	Wrk_CommState:=FALSE;
END_IF;

// Input
Ext_UPS_Data.EXT_Operator.Input_Voltage_L1N := 		HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[7], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Input_Voltage_L2N := 		HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[8], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Input_Voltage_L3N := 		HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[9], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Input_Frequency :=			HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[14], UnvalidValue:=16#FFFF) *0.1;

// Bypass
Ext_UPS_Data.EXT_Operator.Bypass_Voltage_L1N := 		-1;
Ext_UPS_Data.EXT_Operator.Bypass_Voltage_L2N := 		-1;
Ext_UPS_Data.EXT_Operator.Bypass_Voltage_L3N := 		-1;
Ext_UPS_Data.EXT_Operator.Bypass_Frequency :=			-1;

// Output
Ext_UPS_Data.EXT_Operator.Output_Voltage_L1N:=  		HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[0], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Output_Voltage_L2N:=  		HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[1], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Output_Voltage_L3N:=  		HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[2], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Output_Load_L1:= 				HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[3], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Output_Load_L2:= 				HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[4], UnvalidValue:=16#FFFF);
Ext_UPS_Data.EXT_Operator.Output_Load_L3:= 				HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[5], UnvalidValue:=16#FFFF);

//Battery
Ext_UPS_Data.EXT_Operator.Battery_Voltage:=				HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[13], UnvalidValue:=16#FFFF) * 0.1;
Ext_UPS_Data.EXT_Operator.Battery_ChargeLevel:=		-1;

//Common
Ext_UPS_Data.EXT_Operator.Com_Temperature:=			HE_WORD_CheckValid(Word_1:=Inp_HoldingRegister[12], UnvalidValue:=16#FFFF) *0.1;
Ext_UPS_Data.EXT_Operator.Com_Nom_ActivePower:= -1;
Ext_UPS_Data.EXT_Operator.Com_Nom_BatteryCap:=	-1;
Ext_UPS_Data.EXT_Operator.Com_BatteryCharged:=		Inp_HoldingRegister[18] = 16#0;
Ext_UPS_Data.EXT_Operator.Com_InputPresent:=			Inp_HoldingRegister[23] = 16#0;
Ext_UPS_Data.EXT_Operator.Com_NormalOperation:=	Inp_HoldingRegister[32] = 16#0;
Ext_UPS_Data.EXT_Operator.Com_OutputPowered:=		Inp_HoldingRegister[31] = 16#0;

// Alarms
Wrk_State[1]:=Wrk_CommState;
Wrk_Suffix[1]:='Communication fault';
Wrk_State[2]:=	 Inp_HoldingRegister[18] <>16#0 OR Inp_HoldingRegister[20] <>16#0 OR Inp_HoldingRegister[21] <>16#0;
Wrk_Suffix[2]:='Battery fault';
Wrk_State[3]:= Inp_HoldingRegister[22] <>16#0;
Wrk_Suffix[3]:='Over temperature';
Wrk_State[4]:=	Inp_HoldingRegister[22] <>16#0;
Wrk_Suffix[4]:='Input power fault';
Wrk_State[5]:=	Inp_HoldingRegister[39] <>16#0 OR 	Inp_HoldingRegister[40] <>16#0;
Wrk_Suffix[5]:='Shutdown ongoing';
Wrk_State[6]:=Inp_HoldingRegister[30] <>16#0;
Wrk_Suffix[6]:='Charger fail';
Wrk_State[7]:=16#0 <> Inp_HoldingRegister[26];
Wrk_Suffix[7]:='Bypass mode';
Wrk_State[8]:=16#0 <> Inp_HoldingRegister[25];
Wrk_Suffix[8]:='Output overload';
Wrk_State[9]:=16#0 <> Inp_HoldingRegister[34];
Wrk_Suffix[9]:='Internal fuse failiure';

(*************************************************************************
 *	EXCECUTING LOGIC BLOCK
 *************************************************************************)

FB_Data_Logic(Ext_Alarm:=						Ext_UPS_Data.EXT_Alarm, 
						EXT_Engineering:=			Ext_UPS_Data.EXT_Engineering, 
						Ext_General:=					Ext_UPS_Data.EXT_General, 
						Int_Alarm:=						Int_Alarm, 
						Inp_StateState:=				Wrk_State, 
						Inp_StateSuffix:=				Wrk_Suffix, 
						Inp_AlmSuppressDesc:=	Cfg_AlmSuppressDesc, 
						Inp_AlmSuppress:=			Inp_AlmSuppress);

(*************************************************************************
 *	UPDATING OUTPUT
 *************************************************************************)
 
 //BLOCK
 Sts_Alarm:= FB_Data_Logic.Sts_AlarmTriggered;
 
 //STRUCTURE
 Ext_UPS_Data.EXT_General.Connected_ControlCabinet:=	Cfg_ControlCabinet;
 Ext_UPS_Data.EXT_General.Controlled_FromController:=	Cfg_ControllerName;
 Ext_UPS_Data.EXT_General.Process_TAG:=							Cfg_ProcessTAG;
